-- MIIH: immutable sequential Team IDs, generated by PostgreSQL on successful submission.
-- Safe for existing drafts/registrations. Never changes existing IDs.
-- Back up database before applying. Run once; re-running is idempotent.
BEGIN;

ALTER TABLE public.team_registrations ADD COLUMN IF NOT EXISTS team_id varchar(32);
CREATE UNIQUE INDEX IF NOT EXISTS miih_unique_team_id ON public.team_registrations(team_id);
CREATE SEQUENCE IF NOT EXISTS public.miih_team_id_seq START WITH 2000 INCREMENT BY 1;

-- Preserve continuity if earlier migrations issued IDs using another sequence.
DO $$
DECLARE latest bigint;
BEGIN
  SELECT MAX(substring(team_id FROM '^MIIH([0-9]+)$')::bigint)
  INTO latest FROM public.team_registrations WHERE team_id ~ '^MIIH[0-9]+$';
  IF latest IS NOT NULL THEN
    PERFORM setval('public.miih_team_id_seq',GREATEST(latest,
       (SELECT last_value FROM public.miih_team_id_seq)),true);
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.miih_assign_team_id() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.team_id IS NOT NULL THEN
      RAISE EXCEPTION 'Team ID is database-generated; manual assignment denied';
    END IF;
    IF NEW.status='SUBMITTED' THEN
      NEW.team_id := 'MIIH' || nextval('public.miih_team_id_seq');
    END IF;
  ELSE
    IF NEW.team_id IS DISTINCT FROM OLD.team_id THEN
      RAISE EXCEPTION 'Team ID is immutable';
    END IF;
    IF OLD.team_id IS NULL AND OLD.status IS DISTINCT FROM 'SUBMITTED'
       AND NEW.status='SUBMITTED' THEN
      NEW.team_id := 'MIIH' || nextval('public.miih_team_id_seq');
    END IF;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_miih_assign_team_id ON public.team_registrations;
DROP TRIGGER IF EXISTS trg_miih_generate_team_id ON public.team_registrations;
CREATE TRIGGER trg_miih_assign_team_id
  BEFORE INSERT OR UPDATE ON public.team_registrations
  FOR EACH ROW EXECUTE FUNCTION public.miih_assign_team_id();
COMMIT;

